"use client";
import {ArtemisScope} from "./artemis-scope";
import View0 from "./components/dashboards/variants/04-goals";
export interface ArtemisGoalsDashboardProps {className?:string;}
export function ArtemisGoalsDashboard({className}:ArtemisGoalsDashboardProps){return <ArtemisScope className={`art:min-h-dvh ${className??""}`}><View0/></ArtemisScope>;}

"use client";
// @zeus-internal
import { CalendarDays, CircleCheck, Layers, ListChecks, Users } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import { useId, useMemo, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { ChoiceMenu } from "./04-goals/choice-menu";
import { CYCLES, EVERYONE, formatDay, type Goal, goalProgress, initialCompletion, isOverdue, ownersOf, SNAPSHOT_LABEL, SNAPSHOT_YEAR, STATUS_TABS, type StatusFilter, UPCOMING_LIMIT, VIEWER_NAME, } from "./04-goals/data";
import { GoalRow } from "./04-goals/goal-row";
import { KpiCard } from "./04-goals/kpi-card";
import { ProgressBar } from "./04-goals/progress-bar";
import { StatusTabs } from "./04-goals/status-tabs";
const PREVIEW_FLUSH_CSS = "body>main.py-4:has(>main.\\@container\\/planning){padding-top:0;padding-bottom:0;--preview-viewport-height:100svh}";
type UpcomingItem = {
    key: string;
    goal: string;
    title: string;
    due: string;
    overdue: boolean;
};
export default function DashboardsGoals() {
    const headingId = useId();
    const rowsId = useId();
    const reduce = useReducedMotion();
    const [cycleId, setCycleId] = useState(CYCLES[0].id);
    const [owner, setOwner] = useState(EVERYONE);
    const [status, setStatus] = useState<StatusFilter>("all");
    const [openGoal, setOpenGoal] = useState<string | null>(null);
    const [completion, setCompletion] = useState(initialCompletion);
    const cycle = CYCLES.find((c) => c.id === cycleId) ?? CYCLES[0];
    const owners = useMemo(() => ownersOf(cycle).map((name) => ({ value: name, label: name })), [cycle]);
    const goals = owner === EVERYONE ? cycle.goals : cycle.goals.filter((g) => g.owner === owner);
    const rows = status === "all" ? goals : goals.filter((g) => g.status === status);
    const isDone = (goal: Goal, milestoneId: string) => completion[`${goal.id}/${milestoneId}`] ?? false;
    const milestoneTotal = goals.reduce((sum, g) => sum + g.milestones.length, 0);
    const milestoneDone = goals.reduce((sum, g) => sum + g.milestones.filter((m) => isDone(g, m.id)).length, 0);
    const milestoneShare = milestoneTotal ? (milestoneDone / milestoneTotal) * 100 : 0;
    const openCount = goals.filter((g) => g.status !== "finished").length;
    const attentionCount = goals.filter((g) => g.status === "check-in").length;
    const crews = new Set(goals.map((g) => g.crew)).size;
    const targetProgress = goals.length
        ? Math.round((goals.reduce((sum, g) => sum + goalProgress(g), 0) / goals.length) * 100)
        : 0;
    const upcoming: UpcomingItem[] = goals
        .flatMap((g) => g.milestones
        .filter((m) => !isDone(g, m.id))
        .map((m) => ({
        key: `${g.id}/${m.id}`,
        goal: g.title,
        title: m.title,
        due: m.due,
        overdue: isOverdue({ ...m, done: false }),
    })))
        .sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0))
        .slice(0, UPCOMING_LIMIT);
    const changeCycle = (next: string) => {
        setCycleId(next);
        setOwner(EVERYONE);
        setStatus("all");
        setOpenGoal(null);
    };
    const changeOwner = (next: string) => {
        setOwner(next);
        setOpenGoal(null);
    };
    const changeStatus = (next: StatusFilter) => {
        setStatus(next);
        setOpenGoal(null);
    };
    const showAll = () => {
        setOwner(EVERYONE);
        setStatus("all");
        setOpenGoal(null);
    };
    return (<main aria-labelledby={headingId} className="art:@container/planning art:min-h-screen art:w-full art:bg-muted/20 art:text-foreground">
      <style href="goals-dashboard-flush-preview" precedence="default">
        {PREVIEW_FLUSH_CSS}
      </style>
      <div className="art:mx-auto art:max-w-screen-2xl art:space-y-5 art:px-4 art:py-6 art:@min-[640px]/artemis:px-6 art:@min-[640px]/artemis:py-8 art:@min-[1024px]/artemis:px-8">
        <motion.header className="art:flex art:flex-col art:justify-between art:gap-5 art:@5xl/planning:flex-row art:@5xl/planning:items-end" initial={reduce ? false : { opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.45, ease: ARTEMIS_EASE_OUT }}>
          <div>
            <p className="art:mb-3 art:text-xs art:text-muted-foreground">
              Workspace <span className="art:px-2 art:text-border">/</span>Goals &amp; outcomes
            </p>
            <h1 id={headingId} className="art:text-2xl art:font-normal art:tracking-tight art:@min-[640px]/artemis:text-3xl">
              <span className="art:text-muted-foreground">{"Your goals"},</span>{" "}{VIEWER_NAME}
            </h1>
            <p className="art:mt-3 art:text-sm art:text-muted-foreground">
              Track targets, review progress, and keep the next milestone in view.
            </p>
          </div>
          <div className="art:flex art:flex-wrap art:items-center art:gap-2">
            <ChoiceMenu label="Planning cycle" icon={CalendarDays} value={cycleId} options={CYCLES.map((c) => ({ value: c.id, label: c.label }))} onValueChange={changeCycle}/>
            <ChoiceMenu label="Goal owner" icon={Users} value={owner} options={owners} onValueChange={changeOwner}/>
          </div>
        </motion.header>

        <section aria-label="Key performance indicators" className="art:@container art:w-full art:min-w-0">
          <dl className="art:grid art:gap-4 art:@lg:grid-cols-2 art:@5xl:grid-cols-4">
            <KpiCard label="Open goals" value={openCount} hint={`Across ${crews} crews`} ring={{
            value: goals.length ? (openCount / goals.length) * 100 : 0,
            label: "Share of goals still open",
            tone: "foreground",
        }}/>
            <KpiCard label="Target progress" value={targetProgress} percent hint="Average progress toward each target" ring={{ value: targetProgress, label: "Average target progress", tone: "primary" }}/>
            <KpiCard label="Milestones" value={milestoneDone} total={milestoneTotal} hint="Steps finished along the way" ring={{ value: milestoneShare, label: "Share of milestones finished", tone: "primary" }}/>
            <KpiCard label="Needs attention" value={attentionCount} hint="Behind expected pace or past due" ring={{
            value: goals.length ? (attentionCount / goals.length) * 100 : 0,
            label: "Share of goals needing attention",
            tone: "foreground",
        }}/>
          </dl>
        </section>

        <div className="art:grid art:items-start art:gap-5 art:@5xl/planning:grid-cols-[minmax(0,2.2fr)_minmax(320px,1fr)]">
          <section aria-label="Priority progress" className="art:min-w-0">
            <div className="art:mb-3 art:flex art:flex-wrap art:items-center art:justify-between art:gap-3">
              <h2 className="art:text-xl art:font-medium">Goals</h2>
              <div>
                <StatusTabs items={STATUS_TABS} value={status} onValueChange={changeStatus} ariaLabel="Goal status"/>
              </div>
            </div>
            {rows.length ? (<div className="art:@container/goals art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
                {rows.map((goal) => (<GoalRow key={goal.id} goal={goal} baseId={rowsId} open={openGoal === goal.id} completion={completion} onToggle={() => setOpenGoal((id) => (id === goal.id ? null : goal.id))} onMilestoneChange={(milestoneId, done) => setCompletion((prev) => ({ ...prev, [`${goal.id}/${milestoneId}`]: done }))}/>))}
              </div>) : (<div className="art:rounded-2xl art:border art:border-dashed art:border-border art:bg-background art:px-6 art:py-12 art:text-center">
                <CircleCheck className="art:mx-auto art:size-6 art:text-muted-foreground" aria-hidden="true"/>
                <p className="art:mt-3 art:text-sm">No priorities in this view.</p>
                <ArtemisButton variant="tertiary" className="art:mt-4 art:h-9 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" onClick={showAll}>
                  Show all priorities
                </ArtemisButton>
              </div>)}
          </section>

          <aside className="art:space-y-5">
            <section aria-label="Checkpoint summary" className="art:rounded-2xl art:border art:border-border art:bg-background art:p-5 art:@min-[640px]/artemis:p-6">
              <div className="art:flex art:items-center art:justify-between art:gap-3">
                <h2 className="art:text-xl art:font-medium">Milestone progress</h2>
                <span className="art:grid art:size-9 art:place-items-center art:rounded-full art:border art:border-border art:bg-muted">
                  <ListChecks className="art:size-4 art:text-muted-foreground" aria-hidden="true"/>
                </span>
              </div>
              <p className="art:mt-4 art:text-3xl art:font-medium art:tabular-nums">
                {milestoneDone}
                <span className="art:ml-2 art:text-base art:font-normal art:text-muted-foreground">of {milestoneTotal}</span>
              </p>
              <p className="art:mt-1 art:text-xs art:text-muted-foreground">Milestones reached this cycle</p>
              <ProgressBar label="Cycle checkpoints completed" value={Math.round(milestoneShare)} scale={milestoneTotal ? milestoneDone / milestoneTotal : 0} className="art:mt-4"/>
              <p className="art:mt-4 art:border-t art:border-border art:pt-4 art:text-xs art:leading-5 art:text-muted-foreground">
                Progress is based on each outcome’s starting point and target. Pace is compared with its timeline.
              </p>
            </section>

            <section aria-label="Upcoming checkpoints" className="art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
              <div className="art:flex art:items-center art:justify-between art:gap-3 art:p-5 art:@min-[640px]/artemis:p-6">
                <h2 className="art:text-xl art:font-medium">Upcoming milestones</h2>
                <Layers className="art:size-4 art:text-muted-foreground" aria-hidden="true"/>
              </div>
              <ul className="art:max-h-80 art:overflow-y-auto art:px-5 art:pb-2 art:@min-[640px]/artemis:px-6">
                {upcoming.length ? (upcoming.map((item) => (<li key={item.key} className="art:border-t art:border-border art:py-4">
                      <p className="art:flex art:items-center art:justify-between art:gap-3 art:text-xs art:text-muted-foreground">
                        <span>{item.goal}</span>
                        <span className={item.overdue ? "art:shrink-0 art:text-destructive" : "art:shrink-0"}>
                          {item.overdue ? "Overdue" : formatDay(item.due)}
                        </span>
                      </p>
                      <p className="art:mt-1.5 art:text-sm art:leading-5">{item.title}</p>
                    </li>))) : (<li className="art:pb-5 art:text-sm art:text-muted-foreground">
                    Every checkpoint is complete. Take a moment to review the results.
                  </li>)}
              </ul>
            </section>
          </aside>
        </div>

        <output className="art:sr-only">
          {milestoneDone} of {milestoneTotal} checkpoints complete.
        </output>
        <footer className="art:text-xs art:text-muted-foreground">
          Demo workspace · Snapshot {SNAPSHOT_LABEL}, {SNAPSHOT_YEAR}
        </footer>
      </div>
    </main>);
}

"use client";
// @zeus-internal
import { Check, ChevronDown, type LucideIcon } from "lucide-react";
import { motion, type Transition } from "motion/react";
import { type CSSProperties, type KeyboardEvent, type PointerEvent, useCallback, useEffect, useId, useLayoutEffect, useRef, useState, } from "react";
import { artemisCreatePortal } from "../../../../artemis-scope";
import { ARTEMIS_SPRING_LAYOUT } from "../../../../lib/ease";
import { acquireFocusGuards, hideOthers, lockBodyScroll } from "./modal-layer";
const SIDE_OFFSET = 8;
const COLLISION_PADDING = 12;
const MENU_MIN_WIDTH = 192;
const HIGHLIGHT_TRANSITION: Transition = ARTEMIS_SPRING_LAYOUT;
const DROPDOWN_CSS = `
  @keyframes artemis-ce6bf50-artemis-dropdown-panel-enter {
    from {
