`;
const TRIGGER_CLASS = "art:hover:bg-muted art:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0 art:inline-flex art:h-10 art:items-center art:gap-2 art:rounded-full art:border art:border-border art:bg-background art:px-4 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring";
const CONTENT_CLASS = "art:artemis-animated-dropdown art:relative art:isolate art:z-[120] art:max-h-[var(--radix-dropdown-menu-content-available-height)] art:overflow-y-auto art:rounded-xl art:border art:border-border art:bg-background art:p-1.5 art:text-foreground art:outline-none art:min-w-48";
const ITEM_CLASS = "art:group art:relative art:z-10 art:flex art:min-h-10 art:cursor-default art:select-none art:items-center art:gap-2.5 art:rounded-lg art:px-2.5 art:py-2 art:text-sm art:text-foreground art:outline-none art:data-[highlighted]:text-foreground art:data-[disabled]:pointer-events-none art:data-[disabled]:opacity-45 art:pr-9";
type Placement = {
    x: number;
    y: number;
    availableWidth: number;
    availableHeight: number;
    anchorWidth: number;
    anchorHeight: number;
};
type HighlightBox = {
    x: number;
    y: number;
    width: number;
    height: number;
};
function place(trigger: HTMLElement, menuWidth: number): Placement {
    const rect = trigger.getBoundingClientRect();
    const vw = document.documentElement.clientWidth;
    const vh = document.documentElement.clientHeight;
    const ideal = rect.right - menuWidth;
    const x = Math.round(Math.min(Math.max(ideal, COLLISION_PADDING), vw - COLLISION_PADDING - menuWidth));
    const y = Math.round(rect.bottom + SIDE_OFFSET);
    return {
        x,
        y,
        availableWidth: vw - COLLISION_PADDING * 2,
        availableHeight: Math.round(vh - rect.bottom - SIDE_OFFSET - COLLISION_PADDING),
        anchorWidth: Math.round(rect.width),
        anchorHeight: Math.round(rect.height),
    };
}
export type ChoiceOption<T extends string> = {
    value: T;
    label: string;
};
export function ChoiceMenu<T extends string>({ label, icon: Icon, value, options, onValueChange, }: {
    label: string;
    icon: LucideIcon;
    value: T;
    options: readonly ChoiceOption<T>[];
    onValueChange: (value: T) => void;
}) {
    const triggerId = `radix-${useId()}`;
    const contentId = `${triggerId}-content`;
    const triggerRef = useRef<HTMLButtonElement>(null);
    const contentRef = useRef<HTMLDivElement>(null);
    const itemRefs = useRef<(HTMLDivElement | null)[]>([]);
    const [open, setOpen] = useState(false);
    const [mounted, setMounted] = useState(false);
    const [placement, setPlacement] = useState<Placement | null>(null);
    const [highlighted, setHighlighted] = useState<number | null>(null);
    const [box, setBox] = useState<HighlightBox | null>(null);
    const [boxShown, setBoxShown] = useState(false);
    const openedWithKeyboard = useRef(false);
    const closedByPointer = useRef(false);
    const [pointerFocus, setPointerFocus] = useState(false);
    const [returnFocus, setReturnFocus] = useState(false);
    const current = options.find((o) => o.value === value) ?? options[0];
    const openMenu = useCallback((keyboard: boolean) => {
        const trigger = triggerRef.current;
        if (!trigger)
            return;
        openedWithKeyboard.current = keyboard;
        setPlacement(place(trigger, MENU_MIN_WIDTH));
        setHighlighted(null);
        setMounted(true);
        setOpen(true);
    }, []);
    const closeMenu = useCallback(() => setOpen(false), []);
    useLayoutEffect(() => {
        if (!open)
            return;
        const trigger = triggerRef.current;
        const content = contentRef.current;
        if (!trigger || !content)
            return;
        setPlacement(place(trigger, content.offsetWidth));
        if (openedWithKeyboard.current)
            itemRefs.current[0]?.focus({ preventScroll: true });
        else
            content.focus({ preventScroll: true });
    }, [open]);
    useEffect(() => {
        if (!mounted)
            return;
        const trigger = triggerRef.current;
        if (!trigger)
            return;
        const update = () => {
            const content = contentRef.current;
            const next = place(trigger, content ? content.offsetWidth : MENU_MIN_WIDTH);
            setPlacement((prev) => prev &&
                prev.x === next.x &&
                prev.y === next.y &&
                prev.availableWidth === next.availableWidth &&
                prev.availableHeight === next.availableHeight &&
                prev.anchorWidth === next.anchorWidth &&
                prev.anchorHeight === next.anchorHeight
                ? prev
                : next);
        };
        const observer = new ResizeObserver(update);
        observer.observe(trigger);
        window.addEventListener("resize", update);
        window.addEventListener("scroll", update, true);
        return () => {
            observer.disconnect();
            window.removeEventListener("resize", update);
            window.removeEventListener("scroll", update, true);
        };
    }, [mounted]);
    useEffect(() => {
        if (!open)
            return;
        const body = document.body;
        const prevPointer = body.style.pointerEvents;
        body.style.pointerEvents = "none";
        return () => {
            body.style.pointerEvents = prevPointer;
        };
    }, [open]);
    useEffect(() => {
        if (!mounted)
            return;
        const content = contentRef.current;
        if (!content)
            return;
        const releaseGuards = acquireFocusGuards();
        const unhide = hideOthers(content);
        const unlock = lockBodyScroll();
        return () => {
            unlock();
            unhide();
            releaseGuards();
        };
    }, [mounted]);
    useEffect(() => {
        if (!returnFocus)
            return;
        const timer = window.setTimeout(() => {
            setReturnFocus(false);
            triggerRef.current?.focus({ preventScroll: true });
        }, 0);
        return () => window.clearTimeout(timer);
    }, [returnFocus]);
    useEffect(() => {
        if (!open)
            return;
        const onPointerDown = (event: globalThis.PointerEvent) => {
            const target = event.target as Node | null;
            if (target && (contentRef.current?.contains(target) || triggerRef.current?.contains(target)))
                return;
            closedByPointer.current = true;
            setOpen(false);
        };
        document.addEventListener("pointerdown", onPointerDown, true);
        return () => document.removeEventListener("pointerdown", onPointerDown, true);
    }, [open]);
    const unmount = useCallback(() => {
        setMounted(false);
        setPlacement(null);
        setPointerFocus(closedByPointer.current);
        setReturnFocus(true);
    }, []);
    useLayoutEffect(() => {
        if (highlighted === null)
            return;
