export function initialCompletion(): Record<string, boolean> {
    const done: Record<string, boolean> = {};
    for (const cycle of CYCLES) {
        for (const goal of cycle.goals) {
            for (const milestone of goal.milestones)
                done[`${goal.id}/${milestone.id}`] = milestone.done;
        }
    }
    return done;
}
export function ownersOf(cycle: Cycle): string[] {
    const owners: string[] = [EVERYONE];
    for (const goal of cycle.goals)
        if (!owners.includes(goal.owner))
            owners.push(goal.owner);
    return owners;
}

